export function _renderDayName(options, day: number, abbr: boolean) {
	// const modifiedDay = day + options.firstDay;
	const modifiedDay = day;
	let modifiedDayOfWeek = modifiedDay;
	while (modifiedDayOfWeek >= 7) {
		modifiedDayOfWeek -= 7;
	}

	const { weekdays, weekdaysShort } = options.i18n || {};
	return abbr
		? weekdaysShort[modifiedDayOfWeek]
		: weekdays
		  ? weekdays[modifiedDayOfWeek]
		  : [
					"Sunday",
					"Monday",
					"Tuesday",
					"Wednesday",
					"Thursday",
					"Friday",
					"Saturday",
			  ][modifiedDayOfWeek];
}

export function _renderDay(options) {
	const array = [];
	if (options.isEmpty) {
		if (options.showDaysInNextAndPreviousMonths) {
			array.push("is-outside-current-month");

			if (!options.enableSelectionDaysInNextAndPreviousMonths) {
				array.push("is-selection-disabled");
			}
		} else {
			return '<td class="is-empty"></td>';
		}
	}
	if (options.isDisabled) {
		array.push("is-disabled");
	}
	if (options.isToday) {
		array.push("is-today");
	}
	if (options.isSelected) {
		array.push("is-selected");
	}
	if (options.hasEvent) {
		array.push("has-event");
	}
	if (options.isInRange) {
		array.push("is-inrange");
	}
	if (options.isStartRange) {
		array.push("is-startrange");
	}
	if (options.isEndRange) {
		array.push("is-endrange");
	}
	return array;
}
