function moveFocusToDay(day: Date, self) {
	const d = self.focusDay;
	self.focusDay = day;

	if (
		d.getMonth() !== self.focusDay.getMonth() ||
		d.getFullYear() !== self.focusDay.getFullYear()
	) {
		updateGrid(self);
		setTimeout(() => {
			if (d.getDate() !== self.focusDay.getDate()) {
				self.focusDay.setDate(self.theDay);
				self.setFocusDay();
			} else {
				self.setFocusDay();
			}
		}, 100);
	} else {
		self.setFocusDay();
	}
}

function updateGrid(self) {
	const fd = self.focusDay;
	const currentViewMonth = self.calendars[0].month;
	const currentViewYear = self.calendars[0].year;

	if (fd.getFullYear() !== currentViewYear) {
		if (fd.getFullYear() < currentViewYear) {
			self.handlePrevMonthClick();
		} else {
			self.handleNextMonthClick();
		}
	} else {
		if (fd.getMonth() !== currentViewMonth) {
			if (fd.getMonth() < currentViewMonth) {
				self.handlePrevMonthClick();
			} else {
				self.handleNextMonthClick();
			}
		}
	}
}

export function moveFocusToNextDay(self) {
	const d = new Date(self.focusDay);
	d.setDate(d.getDate() + 1);
	self.theDay = d.getDate();
	moveFocusToDay(d, self);
}

export function moveFocusToPreviousDay(self) {
	const d = new Date(self.focusDay);
	d.setDate(d.getDate() - 1);
	self.theDay = d.getDate();
	moveFocusToDay(d, self);
}

export function moveFocusToNextWeek(self) {
	const d = new Date(self.focusDay);
	d.setDate(d.getDate() + 7);
	self.theDay = d.getDate();
	moveFocusToDay(d, self);
}

export function moveFocusToPreviousWeek(self) {
	const d = new Date(self.focusDay);
	d.setDate(d.getDate() - 7);
	self.theDay = d.getDate();
	moveFocusToDay(d, self);
}

export function moveFocusToFirstDayOfWeek(self) {
	const d = new Date(self.focusDay);
	d.setDate(d.getDate() - d.getDay());
	self.theDay = d.getDate();
	moveFocusToDay(d, self);
}

export function moveFocusToLastDayOfWeek(self) {
	const d: Date = new Date(self.focusDay);
	d.setDate(d.getDate() + (6 - d.getDay()));
	self.theDay = d.getDate();
	moveFocusToDay(d, self);
}
