import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";

import { hasSlot } from "../../utils/slot";
import { getDefaultTime } from "../form-time-picker/util";

/**
 * @since 2.4.0
 * @status experimental
 *
 * @slot footer - The panel's footer content.
 *
 * @part base / panel - The component's base wrapper.
 * @part panel-body - The body of the panel.
 * @part panel-footer - The footer of the panel.
 * @part column - Each column in the time panel.
 * @part column-header - The column header in the time panel.
 * @part column-menu - The menu in each column.
 * @part column-menu-base - The base of the menu in each column.
 * @part column-menu-item - Each item in the menu.
 * @part column-menu-item-text - The text inside each menu item.
 * @part wrapper - The column item's wrapper.
 * @part checked-icon - The container that wraps the checked icon.
 * @part nested - The nested menu item container.
 * @part prefix - The prefix container.
 * @part label - The label of the column item.
 * @part suffix - The suffix container.
 * @part check-mark - The check mark icon.
 * @part icon-checked - The container that wraps the check mark icon.
 * @part trigger-gap - The gap between the trigger and the menu.
 * @part trigger-gap-fixed - The fixed gap between the trigger and the menu.
 */

@Component({
	tag: "hbr-time-panel",
	styleUrl: "time-panel.scss",
	shadow: true,
})
export class TimePanel {
	@Element() host: HTMLHbrTimePanelElement;

	@Prop({ mutable: true }) hours: string[] = Array.from(
		{ length: 24 },
		(_, i: number) => getDefaultTime(i),
	);
	@Prop({ mutable: true }) minutes: string[] = Array.from(
		{ length: 60 },
		(_, i: number) => getDefaultTime(i),
	);
	@Prop({ mutable: true }) seconds: string[] = Array.from(
		{ length: 60 },
		(_, i: number) => getDefaultTime(i),
	);

	/** The hour value. */
	@Prop({ mutable: true, reflect: true }) hour: string;

	/** The minute value. */
	@Prop({ mutable: true, reflect: true }) minute: string;

	/** The second value. */
	@Prop({ mutable: true, reflect: true }) second: string;

	/** The i18n (internationalization) key-value pairs. */
	@Prop() i18n = {
		hour: "Hour",
		min: "Min",
		sec: "Sec",
	};

	/** Show the seconds column if set to true. */
	@Prop({ mutable: true, reflect: true }) showSeconds = false;

	/** Set to true to disable the time-picker. */
	@Prop({ reflect: true }) disabled = false;

	@State() hasFooterSlot = false;

	/** Emitted when menu item is clicked. */
	@Event({ eventName: "hbr-menu-click" }) hbrMenuClick: EventEmitter<{
		type?: string;
		item?: HTMLHbrMenuItemElement;
	}>;

	@Watch("hour")
	@Watch("minute")
	@Watch("second")
	// @ts-ignore
	handleHourChange(_, __, name) {
		this.handleMenuItemChecked(name, this[name]);
	}

	private handleMenuItemChecked(type: string, value) {
		const menu = this.host.shadowRoot.querySelector(
			`hbr-menu[data-type='${type}']`,
		);
		if (menu) {
			const items = Array.from(menu.querySelectorAll("hbr-menu-item")) as [
				HTMLHbrMenuItemElement,
			];
			items.forEach((item) => {
				item.checked = item.value === value;
				if (item.value === value) {
					clearTimeout(this[`${type}-void`]);
					// async needed, scrollIntoView will cancel out the pre scrollIntoView call
					this[`${type}-void`] = setTimeout(
						() => {
							item?.scrollIntoView({ behavior: "auto", block: "nearest" });
						},
						type === "hour" ? 0 : type === "min" ? 50 : 100,
					);
				}
			});
		}
	}

	renderColumn = (header: string, data: string[], type: string) => {
		return (
			<div class="time-panel__column" part="column">
				<div class="time-panel__column-header" part="column-header">
					{header}
				</div>
				<hbr-menu
					class="time-panel__column-body"
					part="column-menu"
					exportparts="base: column-menu-base"
					data-type={
						type === "minute" ? "min" : type === "second" ? "sec" : type
					}
					onHbr-select={(event) => {
						event.preventDefault();
						event.stopPropagation();
						this.hbrMenuClick.emit({
							type,
							item: event.detail?.item,
						});
					}}
				>
					{data.map((d) => (
						<hbr-menu-item
							exportparts="
								base: column-menu-item, wrapper, checked-icon, nested, prefix, label, suffix,
								check-mark, icon-checked, trigger-gap, trigger-gap-fixed
							"
							class="time-panel__column-item"
							value={d}
							checked={this[type] === d}
						>
							<div
								class="time-panel__column-item-text"
								part="column-menu-item-text"
							>
								{d}
							</div>
						</hbr-menu-item>
					))}
				</hbr-menu>
			</div>
		);
	};

	handleSlotchange() {
		this.hasFooterSlot = hasSlot(this.host, "footer");
	}

	render() {
		return (
			<Host>
				<div
					part="panel base"
					class={{
						"time-panel": true,
						"time-panel--hour-min": !this.showSeconds,
						"time-panel--hour-min-sec": this.showSeconds,
						"time-panel--disabled": this.disabled,
						"time-panel--has-footer": this.hasFooterSlot,
					}}
				>
					<div part="panel-body" class="time-panel__body">
						{this.renderColumn(this.i18n.hour, this.hours, "hour")}
						{this.renderColumn(this.i18n.min, this.minutes, "minute")}
						{this.showSeconds &&
							this.renderColumn(this.i18n.sec, this.seconds, "second")}
					</div>
					<div part="panel-footer" class="time-panel__footer">
						<slot name="footer" onSlotchange={() => this.handleSlotchange()} />
					</div>
				</div>
			</Host>
		);
	}
}
