/** Helper Functions */

export function isLeapYear(year: number) {
	return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function isWeekend(date: Date) {
	const day = date.getDay();
	return day === 0 || day === 6;
}

export function getDaysInMonth(year: number, month: number) {
	return [
		31,
		isLeapYear(year) ? 29 : 28,
		31,
		30,
		31,
		30,
		31,
		31,
		30,
		31,
		30,
		31,
	][month];
}

export function isDate(obj) {
	// return obj instanceof Date && !isNaN(obj.getTime());
	return (
		/Date/.test(Object.prototype.toString.call(obj)) &&
		!Number.isNaN(obj.getTime())
	);
}

export function setToStartOfDay(date: Date) {
	if (isDate(date)) date.setHours(0, 0, 0, 0);
}

export function compareDates(day1: Date, day2: Date) {
	// weak date comparison (use setToStartOfDay(date) to ensure correct result)
	return day1.getTime() === day2.getTime();
}

export function adjustCalendar(calendar: { year: number; month: number }) {
	if (calendar.month < 0) {
		calendar.year -= Math.ceil(Math.abs(calendar.month) / 12);
		calendar.month += 12;
	}
	if (calendar.month > 11) {
		calendar.year += Math.floor(Math.abs(calendar.month) / 12);
		calendar.month -= 12;
	}
	return calendar;
}

export function isoWeek(date, firstWeekOfYearMinDays) {
	// Ensure we're at the start of the day.
	date.setHours(0, 0, 0, 0);

	// Thursday in current week decides the year because January 4th
	// is always in the first week according to ISO8601.
	const yearDay = date.getDate();
	const weekDay = date.getDay();
	const dayInFirstWeek = firstWeekOfYearMinDays;
	const dayShift = dayInFirstWeek - 1; // counting starts at 0
	const daysPerWeek = 7;
	const prevWeekDay = (day: number) => (day + daysPerWeek - 1) % daysPerWeek;

	// Adjust to Thursday in week 1 and count number of weeks from date to week 1.
	date.setDate(yearDay + dayShift - prevWeekDay(weekDay));

	const jan4th = new Date(date.getFullYear(), 0, dayInFirstWeek);
	const msPerDay = 24 * 60 * 60 * 1000;
	const daysBetween = (date.getTime() - jan4th.getTime()) / msPerDay;
	const weekNum =
		1 +
		Math.round(
			(daysBetween - dayShift + prevWeekDay(jan4th.getDay())) / daysPerWeek,
		);

	return weekNum;
}

export function lastDayOfMonth(date: Date) {
	if (!(date instanceof Date) || !isDate(date)) {
		return null;
	}
	return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
}

export function isLastDayOfMonth(date: Date) {
	return date.getDate() === lastDayOfMonth(date);
}

export const calendar = {
	isLeapYear,
	isWeekend,
	getDaysInMonth,
	isDate,
	setToStartOfDay,
	compareDates,
	adjustCalendar,
	lastDayOfMonth,
	isLastDayOfMonth,
};
