import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { clock } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";
import {
	autoFillInputValue,
	formatInput,
	formatInputPopover,
	formatToInputValue,
	getDate,
	getDefaultTime,
	getHourMinSec,
	getHourMinSecFromInput,
	isEmpty,
	isInput,
	isPM,
	isValidDate,
	isValidInput,
} from "./util";

let id = 0;

/**
 * @since 0.1.49
 * @status experimental
 */

@Component({
	tag: "hbr-time-picker",
	styleUrl: "time-picker.scss",
	shadow: true,
})
export class TimePicker {
	inputId = `time-picker-${++id}`;
	labelId = `time-picker-label-${id}`;
	_helpTextId = `time-picker-helpTextId-${id}`;
	input: HTMLHbrInputElement;
	select: HTMLHbrSelectElement;
	dropdown: HTMLHbrDropdownElement;
	isValid = true;
	dateString: string;
	onValidating = false;
	unsubscribe: () => void;
	popoverInput: HTMLHbrInputElement;

	_hours: Array<string> = Array.from({ length: 24 }, (_, i: number) =>
		getDefaultTime(i),
	);
	_min: Array<string> = Array.from({ length: 60 }, (_, i: number) =>
		getDefaultTime(i),
	);
	_sec: Array<string> = Array.from({ length: 60 }, (_, i: number) =>
		getDefaultTime(i),
	);

	@Element() host: HTMLHbrTimePickerElement;

	@State() hour = "";
	@State() min = "";
	@State() sec = "";
	@State() hasFocus = false;
	@State() hasContent = false;
	@State() hasHelpTextSlot = false;
	@State() hasLabelSlot = false;
	@State() meridiem = "AM";
	@State() panelOpen = false;

	/** Enable / disable popover panel */
	@Prop({ mutable: true }) popOver = true;

	@Prop({ mutable: true, reflect: true }) distance = 3;

	/** The popover panel fits the trigger or not. */
	@Prop({ mutable: true, reflect: true }) panelFitTrigger = false;

	/** The time-picker's open attribute for popover. */
	@Prop({ reflect: true }) open = false;

	/** The time-picker's name attribute. */
	@Prop({ reflect: true }) name: string;

	/** The time-picker's select hoist option, refer the select doc */
	@Prop({ reflect: true }) hoist = true;

	/**
	 * The preferred placement of the panel. Note that the actual placement may vary as needed to keep the panel
	 * inside of the viewport.
	 */
	@Prop({ reflect: true }) placement:
		| "top"
		| "top-start"
		| "top-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "right"
		| "right-start"
		| "right-end"
		| "left"
		| "left-start"
		| "left-end" = "bottom-start";

	/** time format 12 | 24. */
	@Prop({ mutable: true, reflect: true }) format: "12" | "24" = "12";

	/** The time-picker's value attribute. type ISOString */
	@Prop({ mutable: true }) value: string;

	/** The time-picker's second. */
	@Prop({ mutable: true, reflect: true }) second = false;

	/** date attribute to retain the date. */
	@Prop({ mutable: true }) date: string;

	/** The time-picker's label attribute. */
	@Prop({ reflect: true }) label = "";

	/** The time-picker's input placeholder */
	@Prop({ reflect: true }) placeholder: string;

	/** The time-picker's help text. */
	@Prop({ reflect: true }) helpText = "";

	/** deprecated */
	@Prop({ reflect: true }) helpTextId = "";

	/** Set to true to disable the time-picker. */
	@Prop({ reflect: true }) disabled = false;

	/** Set to true to make the time-picker a required field. */
	@Prop({ reflect: true }) required = false;

	/** Set to true to make the time-picker to error state. */
	@Prop({ reflect: true }) error = false;

	/* time-picker size */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** The i18n (internationalization) key-value pairs. */
	@Prop() i18n = {
		now: "Now",
		ok: "OK",
		hour: "Hour",
		min: "Min",
		sec: "Sec",
		am: "AM",
		pm: "PM",
	};

	/**
	 * This will be true when the control is in an invalid state. Validity in range inputs is determined by the message
	 * provided by the `setCustomValidity` method.
	 */
	@Prop({ mutable: true, reflect: true }) invalid = false;

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("disabled")
	handleDisabledChange() {
		this.input.disabled = this.disabled;
		this.select.disabled = this.disabled;
	}

	/** Emitted when the input loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	/** Emitted when the changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when click. */
	@Event({ eventName: "hbr-click" }) hbrClick: EventEmitter;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	connectedCallback() {
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleHbrChange = this.handleHbrChange.bind(this);
		this.handleValueChange = this.handleValueChange.bind(this);
		this.handleDropdownPanelShow = this.handleDropdownPanelShow.bind(this);
		this.handleHourChange = this.handleHourChange.bind(this);
		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.handleSlotChange();
		if (isValidDate(this.value)) {
			const value = getDate(this.value, this.date);
			this.setMeridiem(value);
		}
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	componentDidLoad() {
		this.handleValueChange();
	}

	/** Simulates a click on the input. */
	@Method()
	async setClick() {
		this.input.click();
	}

	/** Sets focus on the input. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.input.focus(options);
	}

	/** Removes focus from the input. */
	@Method()
	async removeFocus() {
		this.input.blur();
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		return this.input.reportValidity();
	}

	/** Sets a custom validation message. If `message` is not empty, the field will be considered invalid. */
	@Method()
	async setCustomValidity(message: string) {
		this.input.setCustomValidity(message);
		// this.invalid = !this.input?.checkValidity();
	}

	handleBlur() {
		this.hasFocus = false;
		this.hbrBlur.emit();
	}

	handleFocus() {
		this.hasFocus = true;
		this.hbrFocus.emit();
	}

	handleSlotChange() {
		this.hasContent = hasSlot(this.host as unknown as HTMLElement);
		this.hasHelpTextSlot = hasSlot(
			this.host as unknown as HTMLElement,
			"help-text",
		);
		this.hasLabelSlot = hasSlot(this.host as unknown as HTMLElement, "label");
	}

	@Watch("popOver")
	@Watch("second")
	@Watch("format")
	@Watch("value")
	// @ts-ignore
	handleValueChange(_?, __?, name?) {
		if (this.onValidating) return;
		this.handlePopoverValueChange(this.value);
		const value = name === "format" ? this.dateString : this.value;
		if (!this.input) return;
		if (isEmpty(value)) {
			this.input.value = "";
			this.dateString = "";
			this.isValid = true;
			this.meridiem = "AM";
		} else if (value) {
			if (isValidDate(value)) {
				const _value = getDate(value, this.date);
				this.dateString = _value.toISOString();
				this.setMeridiem(_value);
				this.input.value = formatInput(this);
				this.isValid = true;
			} else {
				this.isValid = false;
				this.dateString = this.input.value;
			}
		}
		name &&
			this.hbrChange.emit({
				isValid: this.isValid,
				input: this.input.value,
				value: this.dateString,
			});
	}

	setMeridiem = (value) => {
		const hour = value.getHours();
		if (isPM(hour)) this.meridiem = "PM";
		else this.meridiem = "AM";
	};

	setHourAndMin = (value) => {
		// TODO: with sec
		let { hour, min, sec } = getHourMinSecFromInput(
			value,
			this.format,
			this.second,
		);
		const now = getDate(this.value, this.date);

		if (this.format === "12") {
			if (this.meridiem === "PM") hour = hour === 12 ? 12 : hour + 12;
			else if (this.meridiem === "AM" && hour === 12) hour = 0;
		}

		now.setHours(hour);
		now.setMinutes(min);
		this.second && now.setSeconds(sec);
		if (isValidDate(now)) return now?.toISOString();
		return now?.toString();
	};

	onValidate = (e?, isAutoFill = false) => {
		const inputValue = isInput(e.target) ? e.target.value : this.input.value;

		if (inputValue === "") {
			this.isValid = true;
			this.dateString = "";
			this.value = "";
			return true;
		}

		const value = autoFillInputValue(inputValue, this.format, this.second);
		if (isValidInput(value, this.format, this.second)) {
			const now = this.setHourAndMin(value);
			if (value.trim() !== "") {
				this.dateString = now;
				this.isValid = true;
				if (isAutoFill) this.input.value = value;
				this.value = this.dateString;
				return true;
			}
		} else {
			this.isValid = false;
			this.dateString = value;
			this.value = value;
			return false;
		}
	};

	handleValidation = (e: Event, isAutoFill = false) => {
		if (e.type === "hbr-change") e.stopPropagation();
		this.onValidating = true;
		const isValid = this.onValidate(e, isAutoFill);
		setTimeout(() => {
			this.onValidating = false;
		});
		this.hbrChange.emit({
			isValid,
			input: this.input.value,
			value: this.dateString,
			meridiem: this.meridiem,
		});
	};

	handleFocusout = (e) => {
		this.handleValidation(e, true);
	};

	handleHbrChange = (e) => {
		e.stopPropagation();
	};

	onKeyUp = (e) => {
		if (e && e.key === "Enter") this.handleValidation(e, true);
	};

	handleSelectChange = (e) => {
		this.meridiem = e.target.value;
		this.handleValidation(e);
	};

	renderTrigger = () => {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<div class="time-picker--trigger" slot="trigger">
				<hbr-input
					label={this.label}
					required={this.required}
					error={this.error}
					size={this.size}
					disabled={this.disabled}
					part="input"
					exportparts="
						error-icon:input-error-icon, label, element, base: input-base, clear-button,
						input: input-input, help-text, prefix, suffix
				  	"
					helpText={this.helpText}
					ref={(e) => {
						this.input = e;
					}}
					placeholder={
						this.placeholder
							? this.placeholder
							: this.second
							  ? "hh:mm:ss"
							  : "hh:mm"
					}
					onKeyUp={this.onKeyUp}
					onHbr-change={this.handleHbrChange}
					onFocusout={this.handleFocusout}
				>
					<div part="label" slot={this.hasLabelSlot ? "label" : ""}>
						<slot name="label" />
					</div>
					<div part="help-text" slot={this.hasHelpTextSlot ? "help-text" : ""}>
						<slot name="help-text" />
					</div>
					<slot name="input-suffix" slot="suffix">
						{this.popOver && (
							<hbr-icon
								class="time-picker--icon-clock"
								part="suffix-clock"
								asset={customSystemIcons?.clock || clock}
							/>
						)}
					</slot>
				</hbr-input>
				<hbr-select
					part="select"
					class={{
						"time-picker--select": this.format === "12",
					}}
					label={this.label}
					ref={(ref) => {
						this.select = ref;
					}}
					disabled={this.disabled}
					value={this.meridiem}
					size={this.size}
					onHbr-change={this.handleSelectChange}
					onClick={(e) => {
						if (this.popOver) {
							this.dropdown.open = false;
							e.stopPropagation();
						}
					}}
					exportparts="
						select-anchor,
						error-icon: select-error-icon, label: select-label, element: select-element, base: select-base"
				>
					<hbr-option value="AM">{this.i18n.am}</hbr-option>
					<hbr-option value="PM">{this.i18n.pm}</hbr-option>
				</hbr-select>
			</div>
		);
	};

	/**
	 * Popover logic
	 */
	handleDropdownPanelShow() {
		if (this.popOver) {
			const helpText = this.input?.shadowRoot?.querySelector(
				".form-control__help-text",
			);
			// @ts-ignore
			const offset = helpText?.offsetHeight;
			if (
				helpText &&
				window.getComputedStyle(helpText, null).display === "block"
			)
				this.dropdown.distance = -offset - this.distance;
			else this.dropdown.distance = this.distance;
			const hourMinSec = getHourMinSec(this.input?.value);
			if (hourMinSec) {
				this.setHourMinSec(hourMinSec);
				const { hour, min, sec } = hourMinSec;
				this.handleMenuItemChecked("hour", hour);
				this.handleMenuItemChecked("min", min);
				this.second && this.handleMenuItemChecked("sec", sec);
			}
		}
	}

	setHourMinSec = ({
		hour,
		min,
		sec,
	}: { hour: string; min: string; sec: string }) => {
		this.hour = hour;
		this.min = min;
		if (this.second) {
			this.sec = sec;
		}
	};

	handlePopoverValueChange(newValue) {
		const value = formatToInputValue(
			getDate(newValue, this.date),
			this.second,
			this.format,
		);
		const hourMinSec = newValue
			? getHourMinSec(value)
			: { hour: "", min: "", sec: "" };
		this.setHourMinSec(hourMinSec);
	}

	handleMenuItemClick = (type) => (e) => {
		this[type] = e?.detail?.item.value;
	};

	renderColumn = (header, data, type) => {
		return (
			<div class="time-picker__column" part="column">
				<div class="time-picker__column-header" part="column-header">
					{header}
				</div>
				<hbr-menu
					class="time-picker__column-body"
					data-type={type}
					onHbr-select={this.handleMenuItemClick(type)}
					part="column-menu"
				>
					{data.map((d) => (
						<hbr-menu-item
							tabindx="0"
							class="time-picker__column-item"
							value={d}
							part="column-menu-item"
						>
							<div
								class="time-picker__column-item-text"
								part="column-menu-item-text"
							>
								{d}
							</div>
						</hbr-menu-item>
					))}
				</hbr-menu>
			</div>
		);
	};

	handleMenuItemChecked = (type, value) => {
		const menu = this.host.shadowRoot.querySelector(
			`hbr-menu[data-type='${type}']`,
		);
		if (menu) {
			const items = Array.from(menu.querySelectorAll("hbr-menu-item")) as [
				HTMLHbrMenuItemElement,
			];
			items.forEach((item) => {
				item.checked = item.value === value;
				if (item.value === value) {
					clearTimeout(this[`${type}-toid`]);
					// async needed, scrollIntoView will cancel out the pre scrollIntoView call
					this[`${type}-toid`] = setTimeout(
						() => {
							item?.scrollIntoView({ behavior: "auto", block: "nearest" });
						},
						type === "hour" ? 0 : type === "min" ? 50 : 100,
					);
				}
			});
		}
	};

	@Watch("hour")
	@Watch("min")
	@Watch("sec")
	// @ts-ignore
	handleHourChange(_, __, name) {
		this.handleMenuItemChecked(name, this[name]);
	}

	handleNowBtnClick = () => {
		const value = formatInputPopover(this, true).value;
		value && this.setHourMinSec(getHourMinSec(value));
	};

	handleOKBtnClick = () => {
		const { date, value } = formatInputPopover(this);
		const dateString = date.toISOString();
		this.input.value = value;
		this.value = dateString;
		this.dropdown.open = false;
		this.hbrChange.emit({
			isValid: this.isValid,
			value: this.dateString,
			input: value,
		});
	};

	render() {
		return (
			<Host>
				<div
					part="base"
					class={{
						"time-picker": true,
						"time-picker--hour-min": !this.second,
						"time-picker--hour-min-sec": this.second,
						"time-picker--disabled": this.disabled,
					}}
				>
					<hbr-dropdown
						part="dropdown"
						manualTrigger={!this.popOver}
						onHbr-show={this.handleDropdownPanelShow}
						panelFitTrigger={this.panelFitTrigger}
						placement={this.placement}
						autoSize={"both"}
						closeOnSelect={false}
						uncontrolled
						ref={(el) => {
							this.dropdown = el;
						}}
						open={this.open}
						disabled={this.disabled}
						distance={this.distance}
						sentiment="none"
					>
						{this.renderTrigger()}
						<div part="panel" class="time-picker__panel">
							<div part="panel-body" class="time-picker__panel-body">
								{this.renderColumn(this.i18n.hour, this._hours, "hour")}
								{this.renderColumn(this.i18n.min, this._min, "min")}
								{this.second &&
									this.renderColumn(this.i18n.sec, this._sec, "sec")}
							</div>
							<div part="panel-footer" class="time-picker__panel-footer">
								<hbr-button
									part="now-button"
									size="small"
									variant="text"
									onClick={this.handleNowBtnClick}
								>
									{this.i18n.now}
								</hbr-button>
								<hbr-button
									part="ok-button"
									size="small"
									onClick={this.handleOKBtnClick}
								>
									{this.i18n.ok}
								</hbr-button>
							</div>
						</div>
					</hbr-dropdown>
				</div>
			</Host>
		);
	}
}
