import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";
import {
	adjustCalendar,
	compareDates,
	getDaysInMonth,
	isDate,
	isWeekend,
	isoWeek,
	setToStartOfDay,
} from "../../utils/calendar";
import { hasSlot } from "../../utils/slot";
import type { Aria, CalendarConfig, DayConfig } from "./types";
import { _renderDay, _renderDayName } from "./until";

import {
	caretDoubleLeft,
	caretDoubleRight,
	caretLeft,
	caretRight,
} from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

import {
	moveFocusToFirstDayOfWeek,
	moveFocusToLastDayOfWeek,
	moveFocusToNextDay,
	moveFocusToNextWeek,
	moveFocusToPreviousDay,
	moveFocusToPreviousWeek,
} from "./keyboard";

/**
 * @since 2.4.0
 * @status stable
 *
 * @data-testid calendarMonth - The current month heading button in the calendar header.
 * @data-testid calendarYear - The current year heading button in the calendar header.
 * @data-testid prevYear - The previous-year navigation control.
 * @data-testid prevMonth - The previous-month navigation control.
 * @data-testid nextMonth - The next-month navigation control.
 * @data-testid nextYear - The next-year navigation control.
 *
 * @slot - The calendar's content.
 *
 * @part base - The base wrapper
 * @part calendar - The calendar rows
 * @part header - The calendar header
 * @part month-year - The month and year heading
 * @part week-title - The week title
 * @part week - The week rows
 * @part day - The day button
 * @part picker-base - The picker's base wrapper.
 * @part picker-header - The picker's header.
 * @part picker-body - The picker's body.
 */
@Component({
	tag: "hbr-calendar",
	styleUrl: "calendar.scss",
	shadow: true,
})
export class Calendar {
	private dayConfig: DayConfig;
	private multiCalendar: boolean;
	month: number;
	yearValue: number;
	year: number;
	monthValue: number;
	private defaultOptions: CalendarConfig = {
		defaultDate: null,
		firstDay: 0,
		firstWeekOfYearMinDays: 4,
		yearRange: 10,
		showWeekNumber: false,
		pickWholeWeek: false,
		minYear: 0,
		maxYear: 9999,
		isRTL: false,
		yearSuffix: "",
		showMonthAfterYear: false,
		showDaysInNextAndPreviousMonths: false,
		enableSelectionDaysInNextAndPreviousMonths: false,
		numberOfMonths: 1,
		mainCalendar: "left",
		blurFieldOnSelect: true,
		startRange: null,
		endRange: null,
		i18n: {
			previousMonth: "Previous Month",
			previousYear: "Previous Year",
			nextMonth: "Next Month",
			nextYear: "Next Year",
			months: [
				"January",
				"February",
				"March",
				"April",
				"May",
				"June",
				"July",
				"August",
				"September",
				"October",
				"November",
				"December",
			],
			weekdays: [
				"Sunday",
				"Monday",
				"Tuesday",
				"Wednesday",
				"Thursday",
				"Friday",
				"Saturday",
			],
			weekdaysShort: ["S", "M", "T", "W", "T", "F", "S"],
		},
		minMonth: 0,
		maxMonth: 0,
		parse: null,
		disableWeekends: false,
		disableDayFn: null,
		showSixWeeks: true, //Magnetic design shows 6weeks as default to keep the height of the calendar consistent
	};
	private options: CalendarConfig;

	private defaultAria: Aria = {
		role: "dialog",
		label: "Choose Date",
		level: 3,
		prevMonth: "Previous Month",
		prevYear: "Previous Year",
		nextMonth: "Next Month",
		nextYear: "Next Year",
	};
	private hasSelectedDay: boolean;
	private focusDay: Date;
	//@ts-ignore: this is being used on keyboard.ts
	private theDay: number;
	private labelMonth: number | undefined;

	@Element() host: HTMLHbrCalendarElement;

	@State() hasHeaderSlot: boolean;
	@State() hasWeekSlot: boolean;
	@State() hasDaysSlot: boolean;
	@State() setDefaultDate: boolean;
	@State() calendars: { year: number; month: number }[] = undefined;
	@State() date: Date;
	@State() reRender: boolean;
	@State() displayView = "day";

	/** Calendar configuration. */
	@Prop({ mutable: true }) config: CalendarConfig;
	/** Do not use. Deprecation candidate */
	@Prop() arialevel: 3;

	/** Magnetic style. */
	@Prop() square: boolean;

	@Prop() reRenderOnSlotChange: boolean; // deprecate candidate?

	/** Attributes related to screen readers. */
	@Prop() aria: Aria;

	/** Emitted when click. */
	@Event({ eventName: "hbr-day-click" }) hbrDayClick: EventEmitter;

	/** Emitted when day is focused. */
	@Event({ eventName: "hbr-day-focus" }) hbrDayFocus: EventEmitter;

	/** Emitted when keydown. */
	@Event({ eventName: "hbr-day-keydown" }) hbrDayKeydown: EventEmitter;

	@Event({ eventName: "hbr-title-keydown" }) hbrTitleKeydown: EventEmitter;

	/** Emitted when the month view is displayed as a result of a month click event.  */
	@Event({ eventName: "hbr-month-view" }) hbrMonthView: EventEmitter;

	/** Emitted when the year view is displayed as a result of a year click event.  */
	@Event({ eventName: "hbr-year-view" }) hbrYearView: EventEmitter;

	/** Emitted when the default calendar view is displayed from month or year views.  */
	@Event({ eventName: "hbr-day-view" }) hbrDayView: EventEmitter;

	componentWillLoad() {
		let { config, square } = this;
		if (square) {
			this.defaultOptions.i18n.weekdaysShort = [
				"Su",
				"Mo",
				"Tu",
				"We",
				"Th",
				"Fr",
				"Sa",
			];
			this.defaultOptions.i18n.months = [
				"Jan",
				"Feb",
				"Mar",
				"Apr",
				"May",
				"Jun",
				"Jul",
				"Aug",
				"Sep",
				"Oct",
				"Nov",
				"Dec",
			];
		}
		if (config) {
			if (config.numberOfMonths) {
				const numOfMon = config.numberOfMonths || 1;
				config.numberOfMonths = numOfMon > 4 ? 4 : numOfMon;
			}

			if (config.minDate && !isDate(config.minDate)) {
				config.minDate = null;
			} else if (typeof config.minDate === "string") {
				config.minDate = new Date(Date.parse(config.minDate));
			}
			if (!isDate(config.maxDate)) {
				config.maxDate = null;
			}
			if (config.minDate && config.maxDate && config.minDate > config.maxDate) {
				config.maxDate = config.minDate = null;
			}
			if (config.minDate as Date) {
				this.setMinDate(new Date(config.minDate));
			}

			if (Array.isArray(config.yearRange)) {
				const fallback = new Date().getFullYear() - 10;
				const startYear: number = config.yearRange[0] || fallback;
				const endYear: number = config.yearRange[1] || fallback;
				config = { ...config, yearRange: [startYear, endYear] };
			} else {
				config.yearRange =
					Math.abs(config.yearRange) || this.defaultOptions.yearRange;
				if (typeof config.yearRange === "number" && config.yearRange > 100) {
					config.yearRange = 100;
				}
			}
		}

		this.options = { ...this.defaultOptions, ...this.config };
		/** Make sure i18n can have all the items even a user only update one item. */
		this.options.i18n = { ...this.defaultOptions.i18n, ...this.config?.i18n };
		const defDate: Date =
			this.options.defaultDate && new Date(this.options.defaultDate);
		if (isDate(defDate)) {
			if (this.options.setDefaultDate) {
				this.setDate(defDate);
			} else {
				this.gotoDate(defDate);
			}
		} else {
			if (this.options.startRange) {
				this.gotoDate(this.options.startRange);
			} else {
				this.gotoDate(new Date());
			}
		}

		this.multiCalendar = this.options.numberOfMonths > 1;
	}

	componentDidUpdate() {
		this.labelMonth = undefined;
	}

	@Method()
	async getDate() {
		return isDate(this.date) ? new Date(this.date.getTime()) : null;
	}

	@Method()
	async setDate(date: Date, preventOnSelect?: boolean) {
		if (!date) {
			this.date = null;
			return this.draw();
		}
		let _date: Date = date;
		if (typeof date === "string") {
			_date = new Date(Date.parse(date));
		}
		if (!isDate(date)) {
			return;
		}
		const { minDate, maxDate, onSelect } = this.options;
		const min = minDate;
		const max = maxDate;
		if (isDate(min) && date < min) {
			_date = min as Date;
		} else if (isDate(max) && date > max) {
			_date = max as Date;
		}

		this.date = new Date(_date.getTime());
		setToStartOfDay(this.date);
		this.gotoDate(this.date);

		if (!preventOnSelect && typeof onSelect === "function") {
			this.options.onSelect.call(this, this.date, false);
		}
	}

	@Method()
	async clear() {
		this.setDate(null);
	}

	@Method()
	async gotoDate(date: Date) {
		let newCalendar = true;

		if (!isDate(date)) {
			return;
		}
		if (this.calendars) {
			const firstVisibleDate = new Date(
				this.calendars[0].year,
				this.calendars[0].month,
				1,
			);
			const lastVisibleDate = new Date(
				this.calendars[this.calendars.length - 1].year,
				this.calendars[this.calendars.length - 1].month,
				1,
			);
			const visibleDate = date.getTime();
			// get the end of the month
			lastVisibleDate.setMonth(lastVisibleDate.getMonth() + 1);
			lastVisibleDate.setDate(lastVisibleDate.getDate() - 1);
			newCalendar =
				visibleDate < firstVisibleDate.getTime() ||
				lastVisibleDate.getTime() < visibleDate;
		}
		if (newCalendar) {
			this.calendars = [
				{
					month: date.getMonth(),
					year: date.getFullYear(),
				},
			];
			if (this.options.mainCalendar === "right") {
				this.calendars[0].month += 1 - this.options.numberOfMonths;
			}
		}
		this.adjustCalendars();
	}
	@Method()
	async adjustCalendars() {
		this.calendars[0] = adjustCalendar(this.calendars[0]);
		for (let c = 1; c < this.options.numberOfMonths; c++) {
			this.calendars[c] = adjustCalendar({
				month: this.calendars[0].month + c,
				year: this.calendars[0].year,
			});
		}
		this.draw();
	}

	@Method()
	async gotoToday() {
		this.gotoDate(new Date());
	}

	/** change view to a specific month (zero-index, e.g. 0: January) */
	@Method()
	async gotoMonth(month: number) {
		this.calendars[0].month = month;
		this.adjustCalendars();
	}

	@Method()
	async nextMonth() {
		this.calendars[0].month++;
		this.adjustCalendars();
	}

	@Method()
	async prevMonth() {
		this.calendars[0].month--;
		this.adjustCalendars();
	}

	/** change view to a specific full year (e.g. "2036") */
	@Method()
	async gotoYear(year: number) {
		this.calendars[0].year = year;
		this.adjustCalendars();
	}

	/** change the minDate */

	@Method()
	async setMinDate(value: Date) {
		const { defaultOptions } = this;
		if (value instanceof Date) {
			setToStartOfDay(value);
			this.options = {
				...this.options,
				minDate: value,
				minYear: value.getFullYear(),
				minMonth: value.getMonth(),
			};
		} else {
			this.options = {
				...this.options,
				minDate: defaultOptions.minDate,
				minYear: defaultOptions.minYear,
				minMonth: defaultOptions.minMonth,
			};
		}
		this.draw();
	}
	@Method()
	async setMaxDate(value: Date) {
		const { defaultOptions } = this;
		if (value instanceof Date) {
			setToStartOfDay(value);
			this.options = {
				...this.options,
				maxDate: value,
				maxYear: value.getFullYear(),
				maxMonth: value.getMonth(),
			};
		} else {
			this.options = {
				...this.options,
				maxDate: defaultOptions.maxDate,
				maxYear: defaultOptions.maxYear,
				maxMonth: defaultOptions.maxMonth,
			};
		}
		this.draw();
	}

	@Method()
	async setStartRange(value: Date) {
		this.options = { ...this.options, startRange: value };
	}
	@Method()
	async setEndRange(value: Date) {
		this.options = { ...this.options, endRange: value };
	}

	@Method()
	async setFocusDay(date?: number) {
		let day: number;
		if (date) {
			day = date;
		} else {
			day = this.focusDay.getDate();
		}
		const button: HTMLButtonElement = this.host.shadowRoot.querySelector(
			`div:not(.is-disabled)[data-day="${day}"] > button[data-pika-day="${day}"]`,
		);
		button?.focus();
	}

	@Method()
	async draw() {
		const { options } = this;
		const minYear = options.minYear;
		const maxYear = options.maxYear;
		const minMonth = options.minMonth;
		const maxMonth = options.maxMonth;

		if (this.year <= minYear) {
			this.year = minYear;
			if (this.month < minMonth) {
				this.month = minMonth;
			}
		}
		if (this.year >= maxYear) {
			this.year = maxYear;
			if (this.month > maxMonth) {
				this.month = maxMonth;
			}
		}
		this.reRender = !this.reRender;
	}

	@Method()
	async getConfig() {
		return {
			calendars: this.calendars,
			date: this.date,
			displayView: this.displayView,
			options: this.options,
		};
	}

	componentWillRender() {
		this.hasSelectedDay = undefined;
	}

	componentDidRender() {
		if (!this.hasSelectedDay) {
			const todayButton = this.host.shadowRoot.querySelector(
				".is-today > button.pika-day",
			);
			if (todayButton) {
				todayButton.setAttribute("tabindex", "0");
				this.focusDay = new Date(todayButton.getAttribute("aria-label"));
			}
		}
	}

	disconnectedCallback() {
		this.hasSelectedDay = undefined;
	}

	handleSlotChange() {
		this.hasHeaderSlot = hasSlot(this.host, "header");
		this.hasWeekSlot = hasSlot(this.host, "week");
		this.hasDaysSlot = hasSlot(this.host, "days");
	}

	handleDayButtonClick(event: Event) {
		const day = event.target as HTMLButtonElement;
		const { pikaYear, pikaMonth, pikaDay } = day.dataset;

		const _date = new Date(
			Number(pikaYear),
			Number(pikaMonth),
			Number(pikaDay),
		);
		_date.setHours(0, 0, 0, 0);

		this.hbrDayClick.emit({
			event,
			year: Number(pikaYear),
			month: Number(pikaMonth),
			day: Number(pikaDay),
			date: _date,
		});
	}

	handleDayKeyDown(event: KeyboardEvent) {
		const day = event.target as HTMLButtonElement;
		let flag = false;

		switch (event.key) {
			case "Esc":
			case "Escape":
				this.hbrDayKeydown.emit({
					event,
					key: "escape",
					day,
				});
				break;

			case " ":
			case "Spacebar":
				this.handleDayButtonClick(event);
				flag = true;
				break;

			case "Enter":
				this.handleDayButtonClick(event);
				flag = true;
				break;

			case "Tab":
				if (event.shiftKey) {
					const nextYearIcon: HTMLHbrIconButtonElement =
						this.host.shadowRoot.querySelector("[data-testid='nextYear']");
					nextYearIcon.setFocus();
				} else {
					const { nextElementSibling } = this.host.parentElement;
					if (nextElementSibling) {
						this.hbrDayKeydown.emit({
							event,
							key: "tab",
							day,
							nextElementSibling,
						});
					} else {
						const prevYearIcon: HTMLHbrIconButtonElement =
							this.host.shadowRoot.querySelector("[data-testid='prevYear']");
						prevYearIcon.setFocus();
					}
				}
				flag = true;
				break;

			case "Right":
			case "ArrowRight":
				moveFocusToNextDay(this);
				flag = true;
				break;

			case "Left":
			case "ArrowLeft":
				moveFocusToPreviousDay(this);
				flag = true;
				break;

			case "Down":
			case "ArrowDown":
				moveFocusToNextWeek(this);
				flag = true;
				break;

			case "Up":
			case "ArrowUp":
				moveFocusToPreviousWeek(this);
				flag = true;
				break;

			case "PageUp":
				if (event.shiftKey) {
					this.handlePrevYearClick();
				} else {
					this.handlePrevMonthClick();
				}
				this.setFocusDay();
				flag = true;
				break;

			case "PageDown":
				if (event.shiftKey) {
					this.handleNextYearClick();
				} else {
					this.handleNextMonthClick();
				}
				this.setFocusDay();
				flag = true;
				break;

			case "Home":
				moveFocusToFirstDayOfWeek(this);
				flag = true;
				break;

			case "End":
				moveFocusToLastDayOfWeek(this);
				flag = true;
				break;
		}

		if (flag) {
			event.stopPropagation();
			event.preventDefault();
		}
	}

	handleDayFocus(event: FocusEvent) {
		const day = event.target as HTMLButtonElement;
		this.hbrDayFocus.emit({
			event,
			year: Number(day.dataset.pikaYear),
			month: Number(day.dataset.pikaMonth),
			day: Number(day.dataset.pikaDay),
			date: new Date(
				Number(day.dataset.pikaYear),
				Number(day.dataset.pikaMonth),
				Number(day.dataset.pikaDay),
			),
		});
	}

	handleMonthLabelClick(event: MouseEvent | KeyboardEvent) {
		this.displayView = "month";
		this.labelMonth = Number((event.target as HTMLElement).dataset.titleMonth);
		this.hbrMonthView.emit({ event, month: this.labelMonth });
	}
	handleMonthTitleKeyDown(event: KeyboardEvent) {
		if (
			event.key === "Enter" ||
			event.key === " " ||
			event.key === "Spacebar"
		) {
			this.handleMonthLabelClick(event);
		}
	}
	handleYearLabelClick(event: MouseEvent | KeyboardEvent) {
		this.displayView = "year";
		this.hbrYearView.emit({ event, year: this.year });
	}
	handleYearTitleKeyDown(event: KeyboardEvent) {
		if (
			event.key === "Enter" ||
			event.key === " " ||
			event.key === "Spacebar"
		) {
			this.handleYearLabelClick(event);
		}
	}

	renderMonthHeading(month: number) {
		return (
			<span
				part="month-label"
				data-testid="calendarMonth"
				class={"pika-label month pika-select pika-select-month"}
				data-title-month={month}
				role="button"
				aria-label={"Select different month"}
				tabindex="0"
				onClick={this.handleMonthLabelClick.bind(this)}
				onKeyDown={this.handleMonthTitleKeyDown.bind(this)}
			>
				{this.options.i18n.months[month]}
			</span>
		);
	}

	renderYearHeading(year: number) {
		return (
			<span
				part="year-label"
				data-testid="calendarYear"
				class={"pika-label year pika-select pika-select-year"}
				data-title-year={year}
				onClick={this.handleYearLabelClick.bind(this)}
				onKeyDown={this.handleYearTitleKeyDown.bind(this)}
				role="button"
				tabindex="0"
				aria-label={"Select different year"}
			>
				{year}
				{this.options.yearSuffix}
			</span>
		);
	}

	renderDay = (dayConfig) => {
		const array = [];
		let ariaSelected = "false";

		if (dayConfig.isEmpty) {
			if (dayConfig.showDaysInNextAndPreviousMonths) {
				array.push("is-outside-current-month");

				if (!dayConfig.enableSelectionDaysInNextAndPreviousMonths) {
					array.push("is-selection-disabled");
				}
			} else {
				array.push("is-empty");
			}
		}
		if (dayConfig.isDisabled || array.includes("is-selection-disabled")) {
			array.push("is-disabled");
		}
		if (!array.includes("is-outside-current-month")) {
			if (dayConfig.isToday) {
				array.push("is-today");
			}
			if (dayConfig.isSelected) {
				array.push("is-selected");
				ariaSelected = "true";
				this.hasSelectedDay = dayConfig.day;
			}
			if (dayConfig.hasEvent) {
				array.push("has-event");
			}
			if (dayConfig.isInRange) {
				array.push("is-inrange");
				if (dayConfig.lastDay) {
					array.push("is-last-day");
				}
			}
			if (dayConfig.isStartRange) {
				array.push("is-startrange");
				ariaSelected = "true";
			}
			if (dayConfig.isEndRange) {
				array.push("is-endrange");
				ariaSelected = "true";
			}
		}

		let buttonPart = "";
		if (array.includes("is-selection-disabled")) {
			buttonPart += "day-button-disabled";
		} else {
			buttonPart += "day-button";
		}
		if (array.includes("is-selected")) {
			buttonPart += " day-button-selected";
		}
		let cls = "";
		if (dayConfig.isEmpty && !dayConfig.showDaysInNextAndPreviousMonths) {
			cls = "is-empty";
		} else {
			cls = array.join(" ");
		}

		return (
			<div
				data-day={dayConfig.day}
				data-month={dayConfig.month}
				data-year={dayConfig.year}
				class={`td ${cls}`}
			>
				<button
					part={buttonPart}
					class="pika-button pika-day"
					type="button"
					tabindex={array.includes("is-selected") ? "0" : "-1"}
					data-pika-year={dayConfig.year}
					data-pika-month={dayConfig.month}
					data-pika-day={dayConfig.day}
					data-pika-day-of-week={dayConfig.dayOfWeek}
					aria-label={
						navigator.language
							? new Intl.DateTimeFormat(navigator.language, {
									month: "short",
									day: "numeric",
									year: "numeric",
							  }).format(
									new Date().setFullYear(
										dayConfig.year,
										dayConfig.month,
										dayConfig.day,
									),
							  )
							: ""
					}
					onClick={this.handleDayButtonClick.bind(this)}
					disabled={dayConfig.isDisabled || dayConfig.isEmpty}
					onKeyDown={this.handleDayKeyDown.bind(this)}
					onFocus={this.handleDayFocus.bind(this)}
					role="gridcell"
					aria-selected={ariaSelected}
				>
					{dayConfig.day}
				</button>
			</div>
		);
	};

	renderWeek = (
		day: number,
		month: number,
		year: number,
		firstWeekOfYearMinDays: number,
	) => {
		const date = new Date(year, month, day);
		const week = isoWeek(date, firstWeekOfYearMinDays);

		return <div class="pika-week">${week}</div>;
	};

	handlePrevMonthClick() {
		this.calendars[0].month--;
		this.adjustCalendars();
	}
	handleNextMonthClick() {
		this.calendars[0].month++;
		this.adjustCalendars();
	}

	handlePrevYearClick() {
		this.calendars[0].year--;
		this.gotoYear(this.calendars[0].year);
	}
	handleNextYearClick() {
		this.calendars[0].year++;
		this.gotoYear(this.calendars[0].year);
	}
	handleTitleKeyDown(event: KeyboardEvent) {
		if (event.key === "Tab" && event.shiftKey) {
			event.preventDefault();
			event.stopPropagation();
			const { nextElementSibling } = this.host.parentElement;
			if (nextElementSibling) {
				this.hbrTitleKeydown.emit({
					event,
					key: "shift",
					target: "prevYear",
					nextElementSibling,
				});
			} else {
				const activeDay: HTMLButtonElement = this.host.shadowRoot.querySelector(
					"button.pika-day[tabindex='0']",
				);
				activeDay?.focus();
			}
		}
	}

	monthView = (aria: Aria) => {
		const labelMonthValue =
			typeof this.labelMonth === "string"
				? Number(this.labelMonth)
				: this.labelMonth;
		const mainCalendarIndex =
			this.options.mainCalendar === "right"
				? this.options.numberOfMonths - 1
				: 0;

		return (
			<Host
				role={aria.role}
				aria-label={aria.label}
				aria-modal={aria.modal ? "true" : null}
			>
				<hbr-picker
					year={this.yearValue || this.calendars[0].year}
					data={this.options.i18n.months}
					onHbr-previous-year={(event) => {
						const { year } = event.detail;
						this.gotoYear(Number(year));
					}}
					onHbr-next-year={(event) => {
						const { year } = event.detail;
						this.gotoYear(Number(year));
					}}
					onHbr-click={(event) => {
						const { month } = event.detail;
						this.displayView = "day";
						this.hbrDayView.emit({ event });
						this.gotoMonth(month);
					}}
					value={
						Number.isFinite(labelMonthValue)
							? labelMonthValue
							: this.calendars[mainCalendarIndex].month
					}
					disabled={
						this.config?.disableMonths ? [...this.config.disableMonths] : []
					}
					class={"month-picker"}
					part="month-picker"
					variant="month"
					exportparts="base: picker-base, header: picker-header, body: picker-body"
				/>
			</Host>
		);
	};
	yearView = (aria: Aria) => {
		const { yearRange } = this.config;
		const { year, month } = this.dayConfig;
		let _year = year;

		if (month === 0 && new Date().getMonth() !== 0) {
			_year -= 1; //this.dayConfig is set to the next month to display empnty days in calendar
		}

		let startYear: number;
		let endYear: number;
		if (Array.isArray(yearRange)) {
			startYear = yearRange[0];
			endYear = yearRange[1];
		} else {
			startYear = Math.floor(year / 10) * 10;
			endYear = startYear + yearRange - 1;
		}

		const yearData = Array.from({ length: 12 }, (_, i) => {
			const currentYear = startYear - 1 + i;
			return {
				year: currentYear,
				disabled: currentYear < startYear || currentYear > endYear,
			};
		});

		return (
			<Host
				role={aria.role}
				aria-label={aria.label}
				aria-modal={aria.modal ? "true" : null}
			>
				<hbr-picker
					year={this.yearValue || this.calendars[0].year}
					data={yearData}
					onHbr-click={(event) => {
						const { value } = event.detail;
						this.displayView = "day";
						this.hbrDayView.emit({ event });
						this.gotoYear(Number(value));
					}}
					onHbr-year-heading-click={(event) => {
						const { year } = event.detail;
						this.gotoYear(Number(year));
						this.displayView = "year";
					}}
					value={_year}
					part="month-picker"
					variant="year"
					yearRange={yearRange}
					class={"year-picker"}
					exportparts="base: picker-base, header: picker-header, body: picker-body"
				/>
			</Host>
		);
	};

	render() {
		const { options } = this;
		const { numberOfMonths } = options;
		const _aria = { ...this.defaultAria, ...this.aria };

		// const popover = this.host.parentElement?.closest(".date-picker--popover");
		// popover?.classList.remove("picker-view");

		if (this.displayView === "month") {
			// popover?.classList.add("picker-view");
			return this.monthView(_aria);
		}

		if (this.displayView === "year") {
			// popover?.classList.add("picker-view");
			return this.yearView(_aria);
		}

		return (
			<Host
				role={_aria.role}
				aria-label={_aria.label}
				aria-modal={_aria.modal ? "true" : null}
			>
				<div
					part="base"
					class={{
						calendar: true,
						"pika-single": true,
						"hbr-calendar-square": this.square,
						range: this.multiCalendar,
					}}
				>
					{Array.from({ length: numberOfMonths }).map((_, index: number) => {
						const renderID = `pika-title-${Math.random()
							.toString(36)
							.replace(/[^a-z]+/g, "")
							.slice(0, 2)}`;

						const _month = this.calendars[index].month;
						const _year = this.calendars[index].year;

						const now = new Date();
						const daysInMonth = getDaysInMonth(_year, _month);
						let before = new Date(_year, _month, 1).getDay();
						let row = [];
						setToStartOfDay(now);
						if (options.firstDay > 0) {
							before -= options.firstDay;
							if (before < 0) {
								before += 7;
							}
						}
						const previousMonth = _month === 0 ? 11 : _month - 1;
						const nextMonth = _month === 11 ? 0 : _month + 1;
						const yearOfPreviousMonth = _month === 0 ? _year - 1 : _year;
						const yearOfNextMonth = _month === 11 ? _year + 1 : _year;
						const daysInPreviousMonth = getDaysInMonth(
							yearOfPreviousMonth,
							previousMonth,
						);
						let cells = daysInMonth + before;
						let after = cells;
						while (after > 7) {
							after -= 7;
						}
						cells += 7 - after;
						let isWeekSelected = false;
						const rows = [];

						const lastDay = [];

						for (
							let daysIndex = 0, dayOfWeek = 0;
							daysIndex < cells;
							daysIndex++
						) {
							const day = new Date(_year, _month, 1 + (daysIndex - before));
							const isSelected = isDate(this.date)
								? compareDates(day, this.date)
								: false;
							const isToday = compareDates(day, now);
							/** we are not supporting this */
							// const hasEvent =
							// 	options.events.indexOf(day.toDateString()) !== -1 ? true : false;
							const isEmpty =
								daysIndex < before || daysIndex >= daysInMonth + before;
							let dayNumber = 1 + (daysIndex - before);
							let monthNumber = _month;
							let yearNumber = _year;
							const isStartRange =
								options.startRange && compareDates(options.startRange, day);
							const isEndRange =
								options.endRange && compareDates(options.endRange, day);
							const isInRange =
								options.startRange &&
								options.endRange &&
								options.startRange < day &&
								day < options.endRange;
							const isDisabled =
								(options.minDate && day < options.minDate) ||
								(options.maxDate && day > options.maxDate) ||
								(options.disableWeekends && isWeekend(day)) ||
								options.disableDayFn?.(day);

							if (isEmpty) {
								if (daysIndex < before) {
									dayNumber = daysInPreviousMonth + dayNumber;
									monthNumber = previousMonth;
									yearNumber = yearOfPreviousMonth;
								} else {
									dayNumber = dayNumber - daysInMonth;
									monthNumber = nextMonth;
									yearNumber = yearOfNextMonth;
								}
							}
							this.dayConfig = {
								day: dayNumber,
								month: monthNumber,
								year: yearNumber,
								// hasEvent: hasEvent,
								isSelected,
								isToday,
								isDisabled,
								isEmpty,
								isStartRange,
								isEndRange,
								isInRange,
								showDaysInNextAndPreviousMonths:
									options.showDaysInNextAndPreviousMonths,
								enableSelectionDaysInNextAndPreviousMonths:
									options.enableSelectionDaysInNextAndPreviousMonths,
								dayOfWeek,
							};

							if (options.pickWholeWeek && isSelected) {
								isWeekSelected = true;
							}

							const _options = {
								...this.dayConfig,
								isRTL: options.isRTL,
								pickWholeWeek: options.pickWholeWeek,
								isRowSelected: isWeekSelected,
							};

							row.push(_options);

							if (++dayOfWeek === 7) {
								if (options.showWeekNumber) {
									row.unshift(
										this.renderWeek(
											daysIndex - before,
											_month,
											_year,
											options.firstWeekOfYearMinDays,
										),
									);
								}

								rows.push(row);
								row = [];
								dayOfWeek = 0;
								isWeekSelected = false;
							}
							lastDay[0] = dayNumber;
							lastDay[1] = monthNumber;
							lastDay[2] = yearNumber;
						}

						let lastRowDay: number = lastDay[0];

						if (rows.length < 6 && options.showSixWeeks) {
							const extraRow = [];
							const extra: {
								year?: number;
								month?: number;
								isDisabled?: boolean;
								isEmpty?: boolean;
							} = {
								isDisabled: true,
								isEmpty: true,
							};

							if (lastRowDay === daysInMonth) {
								/** last day is last day of the week */
								lastRowDay = 1;
								extra.month = _month + lastDay[1] > 11 ? 0 : _month + 1;
								extra.year = lastDay[2] + 1;
							} else {
								/** continue with same month */
								lastRowDay++;
								extra.month = lastDay[1];
								extra.year = lastDay[2];
							}

							for (let dayIndex = 1; dayIndex < 8; dayIndex++) {
								const lastDayConfig = {
									day: lastRowDay,
									...extra,
								};
								extraRow.push(lastDayConfig);
								lastRowDay++;
							}
							rows.push(extraRow);
						}

						const customSystemIcons = getBootstrapConfig()?.systemIcons;

						return (
							<div
								part="calendar"
								class={`pika-lendar calendar__${index} ${this.displayView}`}
							>
								{this.hasHeaderSlot ? (
									<div part="header" class="calendar__prefix">
										<slot
											name="header"
											onSlotchange={this.handleSlotChange.bind(this)}
										/>
									</div>
								) : (
									<div class={"calendar__header pika-title"}>
										<div class={"pika-title-prev-icons"}>
											<hbr-icon-button
												data-testid="prevYear"
												asset={
													customSystemIcons?.["caret-double-left"] ||
													caretDoubleLeft
												}
												onClick={this.handlePrevYearClick.bind(this)}
												onKeyDown={this.handleTitleKeyDown.bind(this)}
												class={`pika-prev-year 
													${
														this.multiCalendar &&
														index === this.options.numberOfMonths - 1
															? "hidden"
															: ""
													}
														`}
												arialabel={_aria.prevYear}
											/>
											<hbr-icon-button
												asset={customSystemIcons?.["caret-left"] || caretLeft}
												data-testid="prevMonth"
												class={`pika-prev
													${
														this.multiCalendar &&
														index === this.options.numberOfMonths - 1
															? "hidden"
															: ""
													}
														`}
												onClick={this.handlePrevMonthClick.bind(this)}
												arialabel={_aria.prevMonth}
											/>
										</div>
										<div
											aria-live="polite"
											class={"calendar__month-year pika-title-text"}
											role={"heading"}
											aria-level={_aria.level || this.arialevel}
											id={renderID}
										>
											{options.showMonthAfterYear ? (
												<Fragment>
													{this.renderYearHeading(this.calendars[index].year)}
													{this.renderMonthHeading(this.calendars[index].month)}
												</Fragment>
											) : (
												<Fragment>
													{this.renderMonthHeading(this.calendars[index].month)}
													{this.renderYearHeading(this.calendars[index].year)}
												</Fragment>
											)}
										</div>
										<div class={"pika-title-next-icons"}>
											<hbr-icon-button
												asset={customSystemIcons?.["caret-right"] || caretRight}
												arialabel={_aria.nextMonth}
												data-testid="nextMonth"
												class={`pika-next
													${this.multiCalendar && index === 0 ? "hidden" : ""}
													`}
												onClick={this.handleNextMonthClick.bind(this)}
											/>
											<hbr-icon-button
												asset={
													customSystemIcons?.["caret-double-right"] ||
													caretDoubleRight
												}
												arialabel={_aria.nextYear}
												data-testid="nextYear"
												class={`
													pika-next-year ${
														this.multiCalendar && index === 0 ? "hidden" : ""
													}`}
												onClick={this.handleNextYearClick.bind(this)}
											/>
										</div>
									</div>
								)}

								{/** table */}
								<div
									class="calendar__content pika-table"
									part="calendar-content"
									role="grid"
								>
									<div class={"thead"} role="rowgroup">
										<div
											role="row"
											class={"calendar__week-title tr"}
											part="week-title"
										>
											{this.hasWeekSlot && (
												<slot
													name="week"
													onSlotchange={this.handleSlotChange.bind(this)}
												/>
											)}

											{Array.from({ length: 7 }).map((_, i) => (
												<span
													role="columnheader"
													aria-colindex={i + 1}
													part="thead"
													class={"th"}
												>
													<abbr title={_renderDayName(options, i, null)}>
														{_renderDayName(options, i, true)}
													</abbr>
												</span>
											))}
										</div>
									</div>
									<div class={"tbody"}>
										{rows.map((row) => {
											return (
												<div
													role="row"
													class={`calendar__week pika-row ${
														row.pickWholeWeek ? " pick-whole-week" : ""
													}  ${row.isRowSelected ? " is-selected" : ""}`}
													part="week"
													aria-selected={row.isRowSelected ? "true" : "false"}
												>
													{row.map((day) => {
														return this.renderDay(day);
													})}
												</div>
											);
										})}
									</div>
								</div>
							</div>
						);
					})}
				</div>
			</Host>
		);
	}
}
